import { createServer } from 'http';
import { Readable } from 'stream';
import { existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * \u56FA\u5B9A\u914D\u7F6E - \u670D\u52A1\u59CB\u7EC8\u8FD0\u884C\u5728 localhost:9000
 */
const SERVER_HOST = 'localhost';
const SERVER_PORT = 9000;
const SERVER_ADDRESS = 'localhost:9000';

/**
 * \u4ECE\u8BF7\u6C42headers\u4E2D\u6784\u5EFA\u5B8C\u6574URL
 * @param {Object} req - Node.js IncomingMessage\u5BF9\u8C61
 * @returns {Object} \u8FD4\u56DE\u5305\u542B { host, path, fullPath } \u7684\u5BF9\u8C61
 */
export function buildURL(req) {

  // \u5C1D\u8BD5\u591A\u79CD\u65B9\u5F0F\u83B7\u53D6\u771F\u5B9Ehost
  const realHost = 
    req.headers['eo-pages-host'] ||
    SERVER_ADDRESS;

  // \u83B7\u53D6\u534F\u8BAE
  // \u6BCF\u4E00\u8DF3\u4EE3\u7406\u90FD\u662F\u5F80 x-forwarded-proto \u8FFD\u52A0\u800C\u4E0D\u662F\u8986\u76D6\uFF0C\u591A\u8DF3\u540E\u5934\u90E8\u4F1A\u662F
  // "http,http"\u3002\u53EA\u6709\u7B2C\u4E00\u6BB5\u662F\u53EF\u7528\u7684 scheme\uFF0C\u62FC\u63A5\u540E\u7684\u6574\u4E32\u4F1A\u8BA9\u4E0B\u9762\u7684 new URL \u629B\u9519\u3002
  const forwardedProto = req.headers['x-forwarded-proto'];
  const protocol = String((Array.isArray(forwardedProto) ? forwardedProto[0] : forwardedProto) || '')
    .split(',')[0]
    .trim()
    .toLowerCase() || 'https';

  // \u6784\u5EFA\u5B8C\u6574URL
  const fullUrlRaw = protocol + '://' + realHost + req.url;
  const urlObj = new URL(fullUrlRaw);
  
  // \u5904\u7406 pathname - \u79FB\u9664\u672B\u5C3E\u7684 /
  let pathname = urlObj.pathname;
  if (pathname !== '/' && pathname.endsWith('/')) {
    pathname = pathname.slice(0, -1);
  }

  // \u6839\u636E\u73AF\u5883\u6784\u5EFA fullPath
  let fullPath = '';
  if (req.headers.host === 'localhost:9000') {
    // localhost \u73AF\u5883\u53EA\u4F7F\u7528 pathname
    fullPath = pathname;
  } else {
    // \u751F\u4EA7\u73AF\u5883\u4F7F\u7528\u5B8C\u6574 URL
    fullPath = protocol + '://' + realHost + req.url;
    // \u79FB\u9664\u672B\u5C3E\u7684 ?
    if (fullPath.endsWith('?')) {
      fullPath = fullPath.slice(0, -1);
    }
  }
  
  return {
    protocol: protocol,
    host: realHost,
    path: pathname,
    fullPath: fullPath
  };
}

/**
 * \u521B\u5EFA\u8BF7\u6C42\u4F53ReadableStream (\u9002\u7528\u4E8E\u9700\u8981\u6D41\u5F0F\u5904\u7406\u7684\u6846\u67B6)
 * @param {Object} req - Node.js IncomingMessage\u5BF9\u8C61
 * @returns {ReadableStream} Web ReadableStream
 */
export function createRequestStream(req) {
  return new ReadableStream({
    start(controller) {
      req.on('data', chunk => {
        controller.enqueue(new Uint8Array(chunk));
      });
      
      req.on('end', () => {
        controller.close();
      });
      
      req.on('error', error => {
        controller.error(error);
      });
    },
    
    cancel() {
      req.destroy();
    }
  });
}

/**
 * \u8BFB\u53D6\u5B8C\u6574\u8BF7\u6C42\u4F53 (\u9002\u7528\u4E8E\u9700\u8981\u4E00\u6B21\u6027\u8BFB\u53D6body\u7684\u6846\u67B6)
 * @param {Object} req - Node.js IncomingMessage\u5BF9\u8C61
 * @returns {Promise<Buffer>} \u8BF7\u6C42\u4F53Buffer
 */
export async function readRequestBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', chunk => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

